{
  "document_type": "project",
  "primary_topic": "printing_mechanics",
  "main_subject": "3D printing filament production",
  "purpose": "Отримання пластикового прутка (філаменту) придатного для використання на 3D принтері.",
  "components": [
    {
      "name": "Брусок",
      "model": "30х20мм",
      "manufacturer": null,
      "role": "основа пляшкоріза"
    },
    {
      "name": "Лезо канцелярського ножа",
      "model": "ширина 18 мм",
      "manufacturer": null,
      "role": "для нарізки пляшок"
    },
    {
      "name": "Шпилька",
      "model": "М6, довжина 400 мм",
      "manufacturer": null,
      "role": "для кріплення"
    },
    {
      "name": "Гайки",
      "model": "М6",
      "manufacturer": null,
      "role": "для кріплення"
    },
    {
      "name": "Гвинти",
      "model": "М2,5 з шайбами",
      "manufacturer": null,
      "role": "для кріплення"
    },
    {
      "name": "Алюмінієвий брусок",
      "model": "25х15х18 мм",
      "manufacturer": null,
      "role": "для виготовлення сопла"
    },
    {
      "name": "Ніхромова проволока",
      "model": "діаметр 0,3 мм, довжина 30 см",
      "manufacturer": null,
      "role": "для нагріву сопла"
    },
    {
      "name": "Термістор",
      "model": "NTC 3950 100 кОм",
      "manufacturer": null,
      "role": "для вимірювання температури"
    },
    {
      "name": "Контролер",
      "model": "Arduino UNO",
      "manufacturer": null,
      "role": "для управління станком"
    },
    {
      "name": "Двигун",
      "model": "12 вольт, 60 об/хв",
      "manufacturer": null,
      "role": "для автоматичної протяжки прутка"
    },
    {
      "name": "Черв’ячний редуктор",
      "model": "1:60",
      "manufacturer": null,
      "role": "для зменшення швидкості обертання"
    }
  ],
  "technical_parameters": [
    {
      "subject": "Діаметр прутка",
      "name": "Діаметр",
      "value": "1.75 мм",
      "unit": "мм"
    },
    {
      "subject": "Площа поперечного перерізу",
      "name": "Площа",
      "value": "2.4 мм2",
      "unit": "мм2"
    },
    {
      "subject": "Температура нагріву",
      "name": "Температура",
      "value": "240°C",
      "unit": "°C"
    },
    {
      "subject": "Ширина смужки",
      "name": "Ширина",
      "value": "6, 8, 10 мм",
      "unit": "мм"
    },
    {
      "subject": "Товщина стінки пляшки",
      "name": "Товщина",
      "value": "0.25, 0.3, 0.4 мм",
      "unit": "мм"
    }
  ],
  "interfaces_protocols": [
    "Arduino IDE"
  ],
  "software_tools": [
    "temperatur_extruder.ino"
  ]
}

